var path=[],pathAjax=(path=location.toString().split("/"))[3];function inter_init(){var e=document.getElementById("searchform-order"),e=e[e.selectedIndex].value;$.ajax({url:"http://192.168.1.1/yii2-consumption/json/outlayadmin/ajaxhandler",type:"POST",data:{order:e,param2:"",_csrf:yii.getCsrfToken()},dataType:"json",success:function(e){var t,o,n=new Array;for([t,o]of Object.entries(e))n.push({value:""+t,text:""+o});console.log(n)},error:function(e,t,o){console.error(e.responseText)}})}function createPoleSelect(e){var t=document.getElementById("searchform-pole");for(n=t.options.length-1;0<=n;n--)t.remove(n);var o=document.createElement("option");o.textContent="",o.value="",o.selected=!0,t.appendChild(o);for(var n=0;n<e.length;n++){var r=document.createElement("option");r.text=e[n].text,r.value=e[n].value,t.options.add(r)}}window.onload=inter_init;